code_question:
def solution():
    items = [ 
        {'weight': 5, 'value': 1}, 
        {'weight': 3, 'value': 5}, 
        {'weight': 4, 'value': 1}, 
        {'weight': 2, 'value': 5}, 
        {'weight': 4, 'value': 2} 
    ]
    capacity = 25
    n = len(items)
    dp = [[0 for _ in range(capacity + 1)] for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(1, capacity + 1):
            if items[i - 1]['weight'] <= w:
                dp[i][w] = max( 
                    items[i - 1]['value'] + dp[i - 1][w - items[i - 1]['weight']],
                    dp[i - 1][w]
                )
            else:
                dp[i][w] = dp[i - 1][w]

    total_value = dp[n][capacity]
    selected_items = []
    i = n
    w = capacity
    while i > 0 and w > 0:
        if dp[i][w] != dp[i - 1][w]:
            selected_items.append(i - 1)
            w -= items[i - 1]['weight']
        i -= 1

    return True, total_value, selected_items

